-- Additive quotation system. Review and apply with the Supabase CLI; do not run directly in production.
create extension if not exists pgcrypto;
create type public.client_type as enum ('individual', 'company');
create type public.quote_request_status as enum ('new', 'reviewing', 'converted', 'closed');
create type public.quote_status as enum ('draft', 'sent', 'viewed', 'accepted', 'rejected', 'expired', 'cancelled', 'payment_pending', 'paid');
create type public.quote_item_type as enum ('catalog', 'custom');
create type public.discount_type as enum ('none', 'fixed', 'percentage');
create type public.payment_method_type as enum ('gateway', 'bank_transfer');
create type public.fee_type as enum ('none', 'fixed', 'percentage');
create type public.fee_paid_by as enum ('seller', 'customer');
create type public.payment_session_status as enum ('created', 'pending', 'completed', 'failed', 'cancelled', 'expired');
create table public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), client_type public.client_type not null default 'company', business_name text, contact_name text not null, email text, phone text, rfc text, tax_regime text, cfdi_use text, fiscal_zip_code text, billing_address jsonb not null default '{}'::jsonb, shipping_address jsonb, notes text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quote_requests (id uuid primary key default gen_random_uuid(), request_number text not null unique, customer_name text not null, company text, email text not null, phone text not null, rfc text, general_notes text, status public.quote_request_status not null default 'new', cart_snapshot jsonb not null check (jsonb_typeof(cart_snapshot) = 'object'), converted_quote_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quotes (id uuid primary key default gen_random_uuid(), quote_number text not null unique, version integer not null default 1 check (version > 0), client_id uuid not null references public.clients(id), request_id uuid references public.quote_requests(id), status public.quote_status not null default 'draft', currency char(3) not null default 'MXN', issue_date date not null default current_date, valid_until date, subtotal numeric(14,2) not null default 0 check (subtotal >= 0), discount_total numeric(14,2) not null default 0 check (discount_total >= 0), shipping_total numeric(14,2) not null default 0 check (shipping_total >= 0), tax_total numeric(14,2) not null default 0 check (tax_total >= 0), withholding_total numeric(14,2) not null default 0 check (withholding_total >= 0), payment_fee_total numeric(14,2) not null default 0 check (payment_fee_total >= 0), grand_total numeric(14,2) not null default 0 check (grand_total >= 0), notes text, terms text, internal_notes text, public_token text not null unique default encode(gen_random_bytes(32), 'hex'), public_token_expires_at timestamptz, accepted_at timestamptz, rejected_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.quote_requests add constraint quote_requests_converted_quote_fk foreign key (converted_quote_id) references public.quotes(id);
create table public.quote_items (id uuid primary key default gen_random_uuid(), quote_id uuid not null references public.quotes(id) on delete cascade, item_type public.quote_item_type not null, product_id uuid, sku text, name text not null, description text, quantity numeric(14,3) not null check (quantity > 0), unit text not null default 'pieza', unit_price numeric(14,2) not null default 0 check (unit_price >= 0), discount_type public.discount_type not null default 'none', discount_value numeric(14,2) not null default 0 check (discount_value >= 0), tax_rate numeric(7,4) not null default 0 check (tax_rate >= 0), withholding_rate numeric(7,4) not null default 0 check (withholding_rate >= 0), line_subtotal numeric(14,2) not null default 0, line_total numeric(14,2) not null default 0, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quote_events (id uuid primary key default gen_random_uuid(), quote_id uuid not null references public.quotes(id) on delete cascade, event_type text not null, actor_id uuid references auth.users(id), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.payment_methods (id uuid primary key default gen_random_uuid(), type public.payment_method_type not null, provider text not null, display_name text not null, is_enabled boolean not null default false, sort_order integer not null default 0, fee_type public.fee_type not null default 'none', fee_value numeric(14,2) not null default 0 check (fee_value >= 0), fee_paid_by public.fee_paid_by not null default 'seller', public_instructions text, private_configuration jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.payment_sessions (id uuid primary key default gen_random_uuid(), quote_id uuid not null references public.quotes(id), provider text not null, external_reference text, amount numeric(14,2) not null check (amount >= 0), currency char(3) not null default 'MXN', fee_amount numeric(14,2) not null default 0, checkout_url text, status public.payment_session_status not null default 'created', provider_response jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.billing_documents (id uuid primary key default gen_random_uuid(), quote_id uuid not null references public.quotes(id), provider text not null, external_id text, status text not null, document_type text not null, pdf_url text, xml_url text, error_message text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index clients_lookup_idx on public.clients (rfc, email, phone); create index quote_requests_status_idx on public.quote_requests(status, created_at desc); create index quotes_status_idx on public.quotes(status, created_at desc); create index quote_items_quote_idx on public.quote_items(quote_id, sort_order); create index quote_events_quote_idx on public.quote_events(quote_id, created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create trigger clients_updated_at before update on public.clients for each row execute function public.set_updated_at(); create trigger quote_requests_updated_at before update on public.quote_requests for each row execute function public.set_updated_at(); create trigger quotes_updated_at before update on public.quotes for each row execute function public.set_updated_at(); create trigger quote_items_updated_at before update on public.quote_items for each row execute function public.set_updated_at(); create trigger payment_methods_updated_at before update on public.payment_methods for each row execute function public.set_updated_at(); create trigger payment_sessions_updated_at before update on public.payment_sessions for each row execute function public.set_updated_at(); create trigger billing_documents_updated_at before update on public.billing_documents for each row execute function public.set_updated_at();
alter table public.admin_users enable row level security; alter table public.clients enable row level security; alter table public.quote_requests enable row level security; alter table public.quotes enable row level security; alter table public.quote_items enable row level security; alter table public.quote_events enable row level security; alter table public.payment_methods enable row level security; alter table public.payment_sessions enable row level security; alter table public.billing_documents enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.admin_users where user_id = auth.uid()) $$;
create policy "admins manage clients" on public.clients for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage requests" on public.quote_requests for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage quotes" on public.quotes for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage quote items" on public.quote_items for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage quote events" on public.quote_events for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage payment methods" on public.payment_methods for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage payment sessions" on public.payment_sessions for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage billing documents" on public.billing_documents for all using (public.is_admin()) with check (public.is_admin());
